export function getSelectionInfo(e){return e?{start:e.selectionStart,end:e.selectionEnd,value:e.value}:null}export function setSelection(e,t,n){if(e){e.focus();try{e.setSelectionRange(t,n)}catch{}}}export function focusEditor(e){e&&e.focus()}export function enableTabIndent(e,t){return!!e&&(e.addEventListener("keydown",function(n){if("Tab"!==n.key)return;n.preventDefault();const o=e.selectionStart,c=e.selectionEnd,i=e.value;e.value=i.substring(0,o)+t+i.substring(c);const u=o+t.length;e.setSelectionRange(u,u),e.dispatchEvent(new Event("input",{bubbles:!0}))}),!0)}